#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public sealed class FleetOrdersCapture:MonoBehaviour
{
 string folder;int count;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Begin(){if(!Environment.GetCommandLineArgs().Contains("-fleet-orders-capture"))return;var go=new GameObject("Fleet order verification");DontDestroyOnLoad(go);go.AddComponent<FleetOrdersCapture>();}
 void Check(bool ok,string message){if(!ok)throw new Exception(message);count++;}
 IEnumerator Start(){folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/FleetOrders"));Directory.CreateDirectory(folder);SaveGames.TestRoot=Path.Combine(folder,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.json");var run=Run();while(true){object next=null;bool more=false;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"checks.txt"),"FAILED "+count+"\n"+ex);Application.Quit(1);yield break;}if(!more)break;yield return next;}File.WriteAllText(Path.Combine(folder,"checks.txt"),count+" Fleet/research checks passed");Application.Quit(0);}
 int I(string key)=>DailyLifeEvents.I(key);
 IEnumerator Run(){yield return null;SaveMenu.StartCampaign(false);yield return new WaitForSecondsRealtime(2);CampaignHUD.Instance.DismissReport();Check(I("iFleet")==3,"new campaign defaults to Golden Horn");Check(PreparationCampaign.Unavailable(10)=="Under development","deferred preparation cannot waste a preparation month");Check(MonasticResearch.Rules.ProgressPerSecret==1000,"1000 point threshold");var baseline=VariableSingleton.Instance.CaptureState();int secrets=I("iSecrets");VariableSingleton.SetInt("iHealers",1);MonasticResearch.ResetForRestore();MonasticResearch.Ensure();VariableSingleton.SetInt("iMonasticActive",1);VariableSingleton.SetInt("iMonasticProgress",998);MonasticResearch.Advance(VariableSingleton.GetDate().AddDays(1));Check(I("iSecrets")==secrets&&MonasticResearch.Progress==999,"999 no secret");MonasticResearch.Advance(VariableSingleton.GetDate().AddDays(2));Check(I("iSecrets")==secrets+1&&MonasticResearch.Progress==0,"1000 awards one secret");
 VariableSingleton.Instance.RestoreValidated(baseline);VariableSingleton.SetInt("iFleetPrepared",1);VariableSingleton.SetInt("iNavalStores",3);VariableSingleton.SetInt("iNavalBase",1);Check(PreparationCampaign.FleetMultiplier(1,false)==1,"no retired multipliers");int gold=I("iMoney"),materials=I("iMaterials");FleetMissionRules.Resolve(1,(a,b)=>b);Check(I("iMoney")==gold+1500&&I("iMaterials")==materials+100&&I("iSecrets")==secrets,"merchant upper limits, no rare hit");FleetMissionRules.Resolve(1,(a,b)=>a);Check(I("iMoney")==gold+2000&&I("iMaterials")==materials+100&&I("iSecrets")==secrets+1,"merchant lower limits and secret hit");
 SharedProvisions.Ensure();SharedProvisions.Set(SharedProvisions.Camp,37.5);double food=SharedProvisions.Stock(SharedProvisions.City);FleetMissionRules.Resolve(0,(a,b)=>b);Check(SharedProvisions.Stock(SharedProvisions.Camp)==0&&SharedProvisions.Stock(SharedProvisions.City)==food+37.5,"fractional captured food conserved and capped");FleetMissionRules.Resolve(0,(a,b)=>b);Check(SharedProvisions.Stock(SharedProvisions.City)==food+37.5,"empty enemy stock creates no food");
 VariableSingleton.Instance.RestoreValidated(baseline);long people=PopulationAccounting.People;int manpower=RecruitmentLogistics.AvailableManpower,inf=I("iInfantry"),arch=I("iArchers"),cav=I("iCavalry"),env=I("iEnvoys"),monks=I("iHealers"),engineers=I("iEngineers"),guards=I("iVarangians");FleetMissionRules.Resolve(4,(a,b)=>a);Check(I("iInfantry")==inf+50&&I("iArchers")==arch+25&&I("iCavalry")==cav,"volunteer minimum regulars");Check(I("iEnvoys")==env+1&&I("iHealers")==monks+1&&I("iEngineers")==engineers+1&&I("iVarangians")==guards+1,"independent rare rolls all succeed");Check(PopulationAccounting.People==people+79,"arrivals counted once in population");Check(RecruitmentLogistics.AvailableManpower>=manpower,"foreign volunteers do not use domestic pool");FleetMissionRules.Resolve(4,(a,b)=>b);Check(I("iInfantry")==inf+150&&I("iArchers")==arch+75&&I("iCavalry")==cav+10,"maximum regulars");Check(I("iHealers")==monks+1&&I("iEnvoys")==env+1,"rare failures independent of regular max");
 foreach(int chance in new[]{2,3,4,10,11}){VariableSingleton.Instance.RestoreValidated(baseline);int e=I("iEnvoys"),m=I("iHealers"),eng=I("iEngineers"),g=I("iVarangians"),secretCount=I("iSecrets");FleetMissionRules.Resolve(4,(a,b)=>a==1&&b==100?chance:b);Check(I("iEnvoys")==e+(chance<=3?1:0)&&I("iVarangians")==g+(chance<=3?1:0),"three percent boundary "+chance);Check(I("iHealers")==m+(chance<=10?4:0)&&I("iEngineers")==eng+(chance<=10?2:0),"ten percent boundary and specialist maxima "+chance);FleetMissionRules.Resolve(1,(a,b)=>a==1&&b==100?chance:b);Check(I("iSecrets")==secretCount+(chance<=2?1:0),"two percent secret boundary "+chance);}
 VariableSingleton.ChangeBool("bStraitsOpen",false);food=SharedProvisions.Stock(SharedProvisions.City);FleetMissionRules.Resolve(2);Check(SharedProvisions.Stock(SharedProvisions.City)==food,"closed straits block grain");Check(!PreparationCampaign.ChangeFleet(2,out _),"closed grain order blocked");VariableSingleton.ChangeBool("bStraitsOpen",true);FleetMissionRules.Resolve(2);Check(SharedProvisions.Stock(SharedProvisions.City)==food+150,"open grain delivery preserved");gold=I("iMoney");int ships=I("iShips");PreparationCampaign.Naval(0);Check(I("iMoney")==gold&&I("iShips")==ships,"deferred preparation has no effects");VariableSingleton.SetInt("iFleet",3);Check(FleetMissionRules.Defence>0,"defensive fire available");for(int n=0;n<30;n++){VariableSingleton.SetInt("iFleetReportDay",0);Check(FleetOperations.CompleteDay()=="","defence produces no reports");}SaveGames.Checkpoint();var save=SaveGames.Read(VariableSingleton.SavePath);VariableSingleton.Instance.RestoreValidated(save.campaign);Check(I("iFleet")==3,"orders saved");
 var council=FindObjectOfType<CouncilUI>(true);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1600,900)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.3f);council.FleetOrders();yield return null;Canvas.ForceUpdateCanvases();Check(GameObject.Find("Fleet mission 2").GetComponentInChildren<Button>().interactable,"grain enabled open");foreach(var t in GameObject.Find("Council screen").GetComponentsInChildren<TMP_Text>())Check(!t.isTextOverflowing,"orders text fits "+t.text);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"orders-"+size.x+".png"));yield return new WaitForSecondsRealtime(.2f);VariableSingleton.ChangeBool("bStraitsOpen",false);council.FleetOrders();yield return null;Check(!GameObject.Find("Fleet mission 2").GetComponentInChildren<Button>().interactable,"grain disabled closed");for(int m=0;m<5;m++){council.ReviewFleetMission(m);yield return null;foreach(var t in GameObject.Find("Council screen").GetComponentsInChildren<TMP_Text>())Check(!t.isTextOverflowing,"review fits "+m);}VariableSingleton.ChangeBool("bStraitsOpen",true);}
 }
}
